 n=e['name'];x,y,z=_point(e,fn,s,t);side=fn in ('east','west');role=ROLES[n];base=MATERIALS[role]['color'];accent=MATERIALS['accent']['color'];dark=MATERIALS['recess']['color'];light=MATERIALS['trim']['color'];col=None
